    public function render(HttpUser $user,array $case,bool $roleAccess=false,array $projection=['revision'=>0,'items'=>[],'photos'=>[],'completedSections'=>[]],string $csrf='',bool $fromConstructionControl=false):string
    {
        $e=[PilotView::class,'e'];$id=(int)$case['id'];$sections='';
        foreach(self::SECTIONS as $index=>$section){$weight=\array_sum(\array_column($section['items'],2));$items='';foreach($section['items']as[$itemId,$name,$share])$items.='<div class="fm2-check-item" data-check-item="'.$itemId.'" data-weight="'.$share.'"><button class="fm2-check-toggle" type="button" role="checkbox" aria-checked="false"><span class="fm2-check-box" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m6 12 4 4 8-9"/></svg></span><span class="fm2-check-label">'.$e($name).'<small data-item-sync>Не отмечено</small></span><span class="fm2-check-weight">+'.$share.'%</span></button><button class="fm2-item-installers" type="button" data-installer-edit><span data-installer-summary>Все монтажники объекта</span><small>Изменить исполнителей</small></button></div>';
