        $body=\str_replace('<div class="fm2-toast"',$dialog.'<div class="fm2-toast"',$body);
        $projectionJson=\base64_encode(\json_encode($projection,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));
